    Bug 1949305 - Fix UIFontSize not affecting the account settings contentFrame windows. r=vineet

    Differential Revision: https://phabricator.services.mozilla.com/D239191

diff --git a/mail/modules/UIFontSize.sys.mjs b/mail/modules/UIFontSize.sys.mjs
index e6a909dde7e..02fb468c850 100644
--- a/mail/modules/UIFontSize.sys.mjs
+++ b/mail/modules/UIFontSize.sys.mjs
@@ -134,7 +134,10 @@ export const UIFontSize = {
    */
   registerWindow(win) {
     if (registeredWindows.has(win)) {
-      console.error("Trying to register the same window twice", win);
+      console.error(
+        "Trying to register the same window twice",
+        win.location.pathname
+      );
       return;
     }

@@ -144,7 +147,7 @@ export const UIFontSize = {
       if (win.document.readyState == "loading") {
         console.error(
           "Trying to register a window before it is fully loaded",
-          win
+          win.location.pathname
         );
         return;
       }
diff --git a/mailnews/base/prefs/content/AccountManager.js b/mailnews/base/prefs/content/AccountManager.js
index d724da6e07b..b0a9cb8a045 100644
--- a/mailnews/base/prefs/content/AccountManager.js
+++ b/mailnews/base/prefs/content/AccountManager.js
@@ -195,11 +195,14 @@ function onLoad() {
         });
       }
     }
-    if (!hasLoaded) {
-      UIFontSize.registerWindow(contentFrame.contentWindow);
-      // TODO: Add the density registration once the account settings style is
-      // updated to support density variations.
-    }
+    // Always add the contentFrame window to the UIFontSize because most of the
+    // sub pages remove themselves on onload. This doesn't happen consistently
+    // and the RSS feed seems to be loading twice.
+    // Accept this temporarily and let the API handle the early return. The
+    // account settings will need to be rebuilt from scratch anyway.
+    UIFontSize.registerWindow(contentFrame.contentWindow);
+    // TODO: Add the density registration once the account settings style is
+    // updated to support density variations.
   });

